INSERT INTO audits (id, site_id, template_id, domain, audit_date, auditor, prepared_by, audit_type, time_range, score, earned, possible, band, summary, source, source_ref, flag, created_by, created_at) VALUES (21, 4, 3, 'maintenance', '2026-09-18', 'Vishal Patel', 'Vishal Patel', 'Internal maintenance walk-through', NULL, 77.7, 50.5, 65, 'improve', 'The walk-through evaluated all 65 applicable check points. CAPICHE scored 50.5 of 65 — 77.7% — which sits in the Needs Improvement band. Weakest areas: PM Records / Safety Training 0%, Fire & Life Safety 40%, Civil / Building 50%, Statutory Documents 57%. 1 Close the fire-safety gaps first — alarm panel fault, missing emergency exit, no drill or training on record. 2 Start a PM and safety-training tracking log — currently zero record-keeping. 3 Repair floor/tile defects in civil areas. 4 Close the critical electrical and water items — distribution board (#11), wiring (#14) and water tank (#41) are all on the 48-hour list. 5 Re-audit three to four weeks after the above are closed.', 'import', 'CAPICHE_Ambli_Inspection_Docket_Bookends.pdf', NULL, 'import', '2026-09-18 12:00:00');
