INSERT INTO audits (id, site_id, template_id, domain, audit_date, auditor, prepared_by, audit_type, time_range, score, earned, possible, band, summary, source, source_ref, flag, created_by, created_at) VALUES (22, 3, 3, 'maintenance', '2026-09-19', 'Vishal Patel', 'Vishal Patel', 'Internal maintenance walk-through', NULL, 72.3, 47, 65, 'improve', 'The walk-through evaluated all 65 applicable check points. CAPICHE scored 47 of 65 — 72.3% — which sits in the Needs Improvement band. Weakest areas: PM Records / Safety Training 0%, Energy Efficiency 0%, Fire & Life Safety 40%, Refrigeration 50%, Waste / Housekeeping 50%. 1 Close the fire-safety gaps first — alarm panel fault, missing emergency exit, no drill or training on record. 2 Start a PM and energy-tracking log — both categories currently score 0%. 3 Complete condenser cleaning and thermometer calibration records in refrigeration. 4 Strengthen cleaning record-keeping and chemical labelling in housekeeping. 5 Re-audit three to four weeks after the above are closed.', 'import', 'CAPICHE_University_Inspection_Docket_Bookends.pdf', NULL, 'import', '2026-09-19 12:00:00');
