INSERT INTO activity (at, actor, site_id, entity, entity_id, action, detail) VALUES ('2026-09-19 12:00:00', 'Vishal Patel', 3, 'audit', 22, 'imported', 'Maintenance visit 1: 72.3%, Needs Improvement');
INSERT INTO audits (id, site_id, template_id, domain, audit_date, auditor, prepared_by, audit_type, time_range, score, earned, possible, band, summary, source, source_ref, flag, created_by, created_at) VALUES (23, 5, 3, 'maintenance', '2026-09-21', 'Vishal Patel', 'Vishal Patel', 'Internal maintenance walk-through', NULL, 72.3, 47, 65, 'improve', 'The walk-through evaluated all 65 applicable check points. AIKO scored 47 of 65 — 72.3% — which sits in the Needs Improvement band. Weakest areas: PM Records / Safety Training 0%, Energy Efficiency 0%, HVAC 33%, Fire & Life Safety 40%, Refrigeration 50%, Waste / Housekeeping 50%. 1 Close the fire-safety gaps first — alarm panel fault, missing emergency exit, no drill or training on record. These carry the highest life-safety and legal exposure. 2 Replace or repair equipment marked completely non-functional — the missing thermometer (#39) and the dishwasher (#32) block food-safety checks entirely. 3 Start a PM and energy-tracking log; both categories currently score 0%. 4 Tighten housekeeping — cover the waste bins and clean the garbage area (#61), and label all cleaning chemicals (#63). 5 Re-audit three to four weeks after the above are closed.', 'import', 'AIKO_Pal_Inspection_Docket_Bookends.pdf', NULL, 'import', '2026-09-21 12:00:00');
