INSERT INTO audits (id, site_id, template_id, domain, audit_date, auditor, prepared_by, audit_type, time_range, score, earned, possible, band, summary, source, source_ref, flag, created_by, created_at) VALUES (24, 1, 3, 'maintenance', '2026-09-22', 'Vishal Patel', 'Vishal Patel', 'Internal maintenance walk-through', NULL, 77.7, 50.5, 65, 'improve', 'The walk-through evaluated all 65 applicable check points. CAPICHE scored 50.5 of 65 — 77.7% — which sits in the Needs Improvement band. Weakest areas: PM Records / Safety Training 0%, Energy Efficiency 0%, HVAC 50%. 1 Complete the refrigeration temperature log (#35) — a critical gap for food-safety traceability. 2 Fix the emergency exit and conduct fire drill/training (#50, #51) — highest life-safety and legal exposure. 3 Start staff safety training records (#64) and a PM/energy-tracking log — both currently at zero. 4 Review civil/building and drainage items flagged in the 60–70% range for medium-priority repairs. 5 Re-audit three to four weeks after the above are closed.', 'import', 'CAPICHE_Vesu_Inspection_Docket_Bookends.pdf', NULL, 'import', '2026-09-22 12:00:00');
