INSERT INTO audits (id, site_id, template_id, domain, audit_date, auditor, prepared_by, audit_type, time_range, score, earned, possible, band, summary, source, source_ref, flag, created_by, created_at) VALUES (25, 2, 3, 'maintenance', '2026-09-23', 'Vishal Patel', 'Vishal Patel', 'Internal maintenance walk-through', NULL, 83.1, 54, 65, 'satisfactory', 'The walk-through evaluated all 65 applicable check points. CAPICHE scored 54 of 65 — 83.1% — which sits in the Satisfactory band. Weakest areas: PM Records / Safety Training 0%. 1 Fix the emergency exit and conduct fire drill/training (#50, #51) — highest life-safety and legal exposure. 2 Investigate the two critical electrical NC items immediately (#11 distribution board, #14 wiring). 3 Start staff safety training records (#64) and a PM-tracking log — currently the only category at 0%. 4 Review Electrical/Power (75%), HVAC (67%) and Drainage/Grease Trap (67%) for the remaining gaps. 5 Re-audit in 2–3 weeks to confirm closure and aim for the Exemplar band (90%+).', 'import', 'CAPICHE_Piplod_Inspection_Docket_Bookends.pdf', NULL, 'import', '2026-09-23 12:00:00');
